def run_app(app, environ):
    return app(environ, None)


class Client:
    def __init__(self, application, use_cookies=True):
        self.application = application
        self.use_cookies = use_cookies

    def open(self, path):
        return run_app(self.application, {"PATH": path})

    def get(self, path):
        return self.open(path)
